import React, { useEffect, useState } from "react";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import Sidebar from "../components/Sidebar";
import "../styles/Lesson.css";

export default function Lesson() {
  const { lessonId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { lesson } = location.state || {};

  const [tutors, setTutors] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [selectedTutor, setSelectedTutor] = useState(null);
  const [signupProcessing, setSignupProcessing] = useState(false);
  const [bookingStatus, setBookingStatus] = useState(null);
  const [bookedSession, setBookedSession] = useState(null);
  const [watchedVideos, setWatchedVideos] = useState({});
  const [currentVideoPlayer, setCurrentVideoPlayer] = useState(null);
  const [activeStep, setActiveStep] = useState(1);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(null);
  const [worksheet1Answers, setWorksheet1Answers] = useState({});
  const [worksheet2Answers, setWorksheet2Answers] = useState({});
  const [worksheet1Submitted, setWorksheet1Submitted] = useState(false);
  const [worksheet2Submitted, setWorksheet2Submitted] = useState(false);
  const [step3Completed, setStep3Completed] = useState(false);
  const [newQuestion, setNewQuestion] = useState("");
  const [newAnswer, setNewAnswer] = useState("");
  const [communityPosts, setCommunityPosts] = useState([
    {
      id: 1,
      author: "Alex Chen",
      type: "question",
      content: "Can someone explain the difference between mitosis and meiosis? I'm confused about when each process happens.",
      timestamp: "2 hours ago",
      replies: 5,
      likes: 12,
    },
    {
      id: 2,
      author: "Jordan Smith",
      type: "answer",
      content: "The scientific method is important because it provides a systematic approach to testing ideas and reducing bias in research. Each step helps ensure the results are reliable and reproducible.",
      timestamp: "1 hour ago",
      replies: 3,
      likes: 8,
    },
    {
      id: 3,
      author: "Maria Rodriguez",
      type: "question",
      content: "How does photosynthesis relate to cellular respiration? Are they opposite processes?",
      timestamp: "30 minutes ago",
      replies: 2,
      likes: 6,
    },
  ]);

  // Videos for Lesson 1 (Biology)
  const lessonVideos = [
    { id: 1, title: "Introduction to Biology", url: "https://www.youtube.com/watch?v=tZE_fQFK8EY&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=2" },
    { id: 2, title: "Scientific Method", url: "https://www.youtube.com/watch?v=xOLcZMw0hd4&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=3" },
    { id: 3, title: "What do Biologists Do?", url: "https://www.youtube.com/watch?v=rgZhDoPgzK8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=4" },
    { id: 4, title: "Organized Life", url: "https://www.youtube.com/watch?v=cjR5zPrVjTc&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=5" },
    { id: 5, title: "Introduction to Ecology", url: "https://www.youtube.com/watch?v=aO3Yp45zmw8&list=PL8dPuuaLjXtPW_ofbxdHNciuLoTRLPMgB&index=6" },
  ];

  // Worksheet 1: Introduction to Biology & Scientific Method (10 Questions)
  const worksheet1Questions = [
    { id: 1, question: "What is the primary focus of biology?", options: ["The study of rocks", "The study of living organisms and life processes", "The study of weather patterns", "The study of stars"], correct: 1 },
    { id: 2, question: "Which step comes first in the scientific method?", options: ["Hypothesis", "Observation", "Conclusion", "Data collection"], correct: 1 },
    { id: 3, question: "What is a hypothesis?", options: ["A proven fact", "An educated guess based on observations", "A final answer", "A type of experiment"], correct: 1 },
    { id: 4, question: "In the scientific method, what follows hypothesis formation?", options: ["Observation", "Experimentation", "Conclusion", "Theory"], correct: 1 },
    { id: 5, question: "What is the purpose of an experiment?", options: ["To prove a theory is always right", "To test a hypothesis under controlled conditions", "To avoid making observations", "To skip the data collection phase"], correct: 1 },
    { id: 6, question: "How is a theory different from a hypothesis?", options: ["A theory is smaller", "A theory is well-tested and supported by much evidence", "They are the same thing", "A theory is just an opinion"], correct: 1 },
    { id: 7, question: "What is a control group in an experiment?", options: ["The group that gets the treatment", "The group kept under normal conditions for comparison", "All groups being studied", "A group that is not observed"], correct: 1 },
    { id: 8, question: "Which of the following is a characteristic of science?", options: ["Uses only personal beliefs", "Based on observation and experimentation", "Never changes", "Requires no evidence"], correct: 1 },
    { id: 9, question: "What should be documented during an experiment?", options: ["Only successful results", "All observations and data collected", "Only what supports your hypothesis", "Nothing needs to be recorded"], correct: 1 },
    { id: 10, question: "What is the final step of the scientific method?", options: ["Data collection", "Experimentation", "Analysis and conclusion", "Making a hypothesis"], correct: 2 },
  ];

  // Worksheet 2: Biologists, Life Organization & Ecology (10 Questions)
  const worksheet2Questions = [
    { id: 1, question: "What do biologists primarily study?", options: ["Rocks and minerals", "Living organisms and their interactions", "Chemical reactions only", "Planetary movements"], correct: 1 },
    { id: 2, question: "Which is the smallest unit of life?", options: ["Tissue", "Organism", "Cell", "Molecule"], correct: 2 },
    { id: 3, question: "What is the correct order of biological organization from smallest to largest?", options: ["Organism → Cell → Organ", "Cell → Organism → Tissue", "Cell → Tissue → Organ → Organism", "Molecule → Tissue → Cell → Organism"], correct: 2 },
    { id: 4, question: "What is ecology?", options: ["The study of cells only", "The study of organisms and their environment", "The study of chemicals", "The study of fossils"], correct: 1 },
    { id: 5, question: "Which term describes all the organisms of one species in an area?", options: ["Community", "Ecosystem", "Population", "Biome"], correct: 2 },
    { id: 6, question: "What is a biome?", options: ["A single organism", "A large geographical area with specific climate and organisms", "A type of cell", "A chemical compound"], correct: 1 },
    { id: 7, question: "In an ecosystem, what role do plants play?", options: ["Consumers only", "Decomposers", "Producers that convert sunlight to energy", "Parasites"], correct: 2 },
    { id: 8, question: "What is the relationship between a parasite and its host?", options: ["Both benefit", "Neither benefits", "Parasite benefits, host is harmed", "Host benefits, parasite is harmed"], correct: 2 },
    { id: 9, question: "What is biodiversity?", options: ["The number of plants only", "The variety of different species and genetic variation", "The number of animals only", "The size of populations"], correct: 1 },
    { id: 10, question: "How do organisms interact with their environment?", options: ["They only consume resources", "They consume resources and produce waste", "They have no effect on environment", "Only plants interact with their environment"], correct: 1 },
  ];

  const user = JSON.parse(localStorage.getItem("user")) || null;

  // Timeline steps for Lesson 1
  const timelineSteps = [
    { id: 1, title: "Watch 5 Videos", completed: Object.keys(watchedVideos).length === 5, current: Object.keys(watchedVideos).length < 5 },
    { id: 2, title: "Book a Tutor", completed: !!bookedSession, current: Object.keys(watchedVideos).length === 5 && !bookedSession },
    { id: 3, title: "Do 2 Worksheets", completed: step3Completed, current: !!bookedSession && !step3Completed },
    { id: 4, title: "Q&A Post", completed: false, current: step3Completed },
    { id: 5, title: "Complete Game", completed: false, current: false },
    { id: 6, title: "Finish Lesson", completed: false, current: false },
  ];

  useEffect(() => {
    if (!lesson) {
      navigate("/");
      return;
    }

    // Mock tutors data for testing
    const mockTutors = [
      {
        id: 101,
        name: "Dr. Sarah Mitchell",
        bio: "Expert in Biology with 10+ years of teaching experience. Specializes in cellular biology and genetics.",
      },
      {
        id: 102,
        name: "Prof. James Chen",
        bio: "Passionate educator with a focus on interactive learning. Great at breaking down complex concepts.",
      },
    ];

    // Mock sessions data for testing - One hour apart, 9 AM to 5 PM daily
    const mockSessions = [];
    let sessionId = 1;
    const startDate = new Date(2026, 0, 8); // Jan 8, 2026
    const endDate = new Date(2026, 0, 21);  // Jan 21, 2026
    const sessionHours = [9, 10, 11, 12, 13, 14, 15, 16, 17]; // 9 AM to 5 PM, one hour apart

    for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
      sessionHours.forEach((hour, idx) => {
        const tutorId = idx % 2 === 0 ? 101 : 102; // Alternate tutors
        mockSessions.push({
          id: sessionId++,
          tutor_id: tutorId,
          session_time: new Date(d.getFullYear(), d.getMonth(), d.getDate(), hour, 0).toISOString(),
          max_spots: 5,
          signed_up_count: Math.floor(Math.random() * 3), // 0-2 people signed up
        });
      });
    }

    async function loadLessonDetails() {
      try {
        // Fetch tutors
        const tRes = await fetch(`http://localhost:8080/lessons/${lessonId}/tutors`);
        if (tRes.ok) {
          const tData = await tRes.json();
          setTutors(tData.tutors && tData.tutors.length > 0 ? tData.tutors : mockTutors);
        } else {
          setTutors(mockTutors);
        }

        // Fetch sessions
        const sRes = await fetch(`http://localhost:8080/lessons/${lessonId}/sessions`);
        if (sRes.ok) {
          const sData = await sRes.json();
          const normalized = (sData.sessions || []).map((ss) => ({
            ...ss,
            spots_left: ss.max_spots - (ss.signed_up_count || ss.signed_up || 0),
          }));
          setSessions(normalized.length > 0 ? normalized : mockSessions.map(s => ({
            ...s,
            spots_left: s.max_spots - s.signed_up_count,
          })));
        } else {
          setSessions(mockSessions.map(s => ({
            ...s,
            spots_left: s.max_spots - s.signed_up_count,
          })));
        }
      } catch (err) {
        console.error("Failed to load lesson details, using mock data:", err);
        setTutors(mockTutors);
        setSessions(mockSessions.map(s => ({
          ...s,
          spots_left: s.max_spots - s.signed_up_count,
        })));
      }
    }

    loadLessonDetails();
  }, [lessonId, lesson, navigate]);

  // Auto-navigate to Step 4 when worksheets are completed
  useEffect(() => {
    if (step3Completed && activeStep !== 4) {
      setActiveStep(4);
    }
  }, [step3Completed]);

  function markVideoWatched(videoId) {
    setWatchedVideos((prev) => ({
      ...prev,
      [videoId]: true,
    }));
    setCurrentVideoPlayer(null);
  }

  function openVideoPlayer(video) {
    setCurrentVideoPlayer(video);
  }

  function closeVideoPlayer() {
    setCurrentVideoPlayer(null);
  }

  function handleStepClick(stepId) {
    // Allow clicking on completed steps or current step, or Step 2 for booking, or Steps 3+ when tutoring booked, or Step 4+ when worksheets done
    const step = timelineSteps.find(s => s.id === stepId);
    if (step && (step.completed || step.current || stepId === 2 || (stepId === 3 && bookedSession) || (stepId >= 4 && step3Completed))) {
      setActiveStep(stepId);
    }
  }

  // Calendar helper functions
  function getDaysInMonth(date) {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  }

  function getFirstDayOfMonth(date) {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  }

  function hasSessionOnDate(date) {
    if (!selectedTutor) return false;
    const tutorSess = sessions.filter(s => s.tutor_id === selectedTutor.id || s.tutorId === selectedTutor.id);
    return tutorSess.some(session => {
      const sessionDate = new Date(session.session_time);
      return sessionDate.getDate() === date.getDate() &&
             sessionDate.getMonth() === date.getMonth() &&
             sessionDate.getFullYear() === date.getFullYear();
    });
  }

  function getSessionsForDate(date) {
    if (!selectedTutor) return [];
    const tutorSess = sessions.filter(s => s.tutor_id === selectedTutor.id || s.tutorId === selectedTutor.id);
    return tutorSess.filter(session => {
      const sessionDate = new Date(session.session_time);
      return sessionDate.getDate() === date.getDate() &&
             sessionDate.getMonth() === date.getMonth() &&
             sessionDate.getFullYear() === date.getFullYear();
    });
  }

  async function handleSignupToSession(session) {
    if (!user) {
      alert("Please log in to book a session");
      return;
    }

    if (session.spots_left === 0) {
      setBookingStatus({ type: "error", message: "This session is full" });
      return;
    }

    setSignupProcessing(true);
    try {
      // Try API first
      const res = await fetch(`http://localhost:8080/sessions/${session.id}/signup`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          user_id: user.id,
          name: user.firstName || "Student",
          email: user.email,
        }),
      });

      let bookingSuccess = false;
      if (res.ok) {
        const data = await res.json();
        setBookedSession(data.session || session);
        bookingSuccess = true;
      } else {
        // If API fails, use mock booking (for testing)
        setBookedSession(session);
        bookingSuccess = true;
      }

      if (bookingSuccess) {
        setBookingStatus({ type: "success", message: "Session booked successfully!" });
        setSessions((prev) =>
          prev.map((p) =>
            p.id === session.id ? { ...p, spots_left: Math.max(0, (p.spots_left || 0) - 1) } : p
          )
        );

        setTimeout(() => setBookingStatus(null), 3000);
      }
    } catch (err) {
      console.error("Booking error:", err);
      // Still allow mock booking on error
      setBookedSession(session);
      setBookingStatus({ type: "success", message: "Session booked successfully!" });
      setSessions((prev) =>
        prev.map((p) =>
          p.id === session.id ? { ...p, spots_left: Math.max(0, (p.spots_left || 0) - 1) } : p
        )
      );
      setTimeout(() => setBookingStatus(null), 3000);
    } finally {
      setSignupProcessing(false);
    }
